import { useState } from "react";
import { PageHeader, Card, Pill, StatCard } from "@/components/shell/Primitives";
import { JsonRenderer } from "@/components/json/JsonRenderer";

const MOCK_AGENTS = [
  { id: "main", name: "Main Agent", status: "running" as const, model: "gpt-4o", tools: ["dbus.list_services", "dbus.introspect", "dbus.call_method"], sessionKey: "agent:main", lastActive: new Date().toISOString(), identity: { name: "DBUS Agent", emoji: "🤖" } },
  { id: "monitor", name: "Monitor Agent", status: "idle" as const, model: "gpt-4o-mini", tools: ["system.exec"], sessionKey: "agent:monitor", lastActive: null, identity: { name: "Monitor", emoji: "👁️" } },
  { id: "security", name: "Security Scanner", status: "stopped" as const, model: "gpt-4o", tools: ["dbus.introspect"], sessionKey: "agent:security", lastActive: null, identity: { name: "SecBot", emoji: "🛡️" } },
];

type Panel = "overview" | "tools" | "files";

export default function AgentsPage() {
  const [selectedId, setSelectedId] = useState<string>("main");
  const [panel, setPanel] = useState<Panel>("overview");
  const agent = MOCK_AGENTS.find((a) => a.id === selectedId);

  return (
    <>
      <PageHeader title="Routable Models" subtitle="LLM gateway model routing and configuration." actions={
        <button className="px-4 py-2 rounded-md border border-border bg-[hsl(var(--bg-elevated))] text-sm font-medium hover:bg-muted/30 transition-colors">Refresh</button>
      } />
      <div className="grid grid-cols-1 lg:grid-cols-[280px_1fr] gap-4">
        {/* Agent list */}
        <Card title="Agents">
          <div className="space-y-1 mt-2">
            {MOCK_AGENTS.map((a) => (
              <button key={a.id} onClick={() => setSelectedId(a.id)}
                className={`w-full text-left p-3 rounded-lg border transition-colors ${selectedId === a.id ? "border-primary/30 bg-primary/5" : "border-transparent hover:bg-muted/30"}`}>
                <div className="flex items-center gap-2">
                  <span className="text-lg">{a.identity?.emoji}</span>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium text-foreground truncate">{a.name}</div>
                    <div className="text-[11px] text-muted-foreground font-mono">{a.model}</div>
                  </div>
                  <Pill variant={a.status === "running" ? "ok" : (a.status as string) === "error" ? "danger" : "default"}>{a.status}</Pill>
                </div>
              </button>
            ))}
          </div>
        </Card>

        {/* Agent detail */}
        {agent && (
          <div className="space-y-4">
            <Card>
              <div className="flex items-center gap-3 mb-4">
                <span className="text-2xl">{agent.identity?.emoji}</span>
                <div>
                  <div className="text-lg font-bold text-foreground">{agent.name}</div>
                  <div className="text-xs text-muted-foreground font-mono">{agent.sessionKey}</div>
                </div>
                <div className="ml-auto flex gap-2">
                  {(["overview", "tools", "files"] as Panel[]).map((p) => (
                    <button key={p} onClick={() => setPanel(p)}
                      className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${panel === p ? "bg-primary/15 text-primary" : "text-muted-foreground hover:text-foreground"}`}>
                      {p.charAt(0).toUpperCase() + p.slice(1)}
                    </button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <StatCard label="Status" value={agent.status} variant={agent.status === "running" ? "ok" : "default"} />
                <StatCard label="Model" value={agent.model} />
                <StatCard label="Tools" value={agent.tools.length} />
              </div>
            </Card>
            {panel === "tools" && (
              <Card title="Tool Access">
                <div className="space-y-1 mt-2">
                  {agent.tools.map((t) => (
                    <div key={t} className="flex items-center justify-between px-3 py-2 rounded-md border border-border">
                      <span className="font-mono text-sm">{t}</span>
                      <Pill variant="ok">allowed</Pill>
                    </div>
                  ))}
                </div>
              </Card>
            )}
            {panel === "overview" && (
              <Card title="Identity">
                <JsonRenderer data={agent} className="mt-2" />
              </Card>
            )}
          </div>
        )}
      </div>
    </>
  );
}

/**
 * Operation-DBUS API types — mirrors the Rust backend data model.
 */

// ── D-Bus Core ──────────────────────────────────────────
export interface DbusService {
  name: string;
  uniqueName: string | null;
  pid: number | null;
  cmdline: string | null;
  bus: "system" | "session";
  isActivatable: boolean;
  interfaces: string[];
  objectPaths: string[];
}

export interface DbusMethod {
  name: string;
  inSignature: string;
  outSignature: string;
}

export interface DbusSignal {
  name: string;
  signature: string;
}

export interface DbusProperty {
  name: string;
  signature: string;
  access: "read" | "write" | "readwrite";
  value?: unknown;
}

// ── Tools ───────────────────────────────────────────────
export interface Tool {
  id: string;
  name: string;
  description: string;
  inputSchema: JsonSchema;
  outputSchema?: JsonSchema;
  category: string;
  enabled: boolean;
  source: "builtin" | "dbus" | "mcp" | "custom";
}

export interface ToolExecution {
  id: string;
  toolId: string;
  input: Record<string, unknown>;
  output: unknown;
  status: "pending" | "running" | "completed" | "error";
  error?: string;
  duration?: number;
  timestamp: string;
}

// ── Agents ──────────────────────────────────────────────
export interface Agent {
  id: string;
  name: string;
  status: "running" | "idle" | "error" | "stopped";
  model: string;
  sessionKey: string;
  tools: string[];
  lastActive: string | null;
  errorMessage?: string;
  identity?: { name?: string; emoji?: string; avatar?: string };
}

// ── LLM ─────────────────────────────────────────────────
export interface LlmProvider {
  id?: string;
  name?: string;
  provider?: string;
  model: string;
  model_non_sandboxed?: boolean;
  endpoint?: string;
  status?: "connected" | "disconnected" | "error";
  available?: boolean;
  available_providers?: string[];
  tokenUsage?: { prompt: number; completion: number; total: number };
}

export interface LlmProvidersResponse {
  providers: string[];
  current: string;
}

export interface LlmModel {
  id: string;
  name: string;
  description?: string;
  available: boolean;
  provider?: string;
  upstream_provider?: string;
  transport?: string;
  status?: string;
  route_hint?: string;
  route_kind?: string;
  status_reason?: string;
  source?: string;
  contextWindow?: number;
  active?: boolean;
}

export interface LlmModelsResponse {
  provider: string;
  models: LlmModel[];
}

// ── Sessions & Chat ─────────────────────────────────────
export interface Session {
  key: string;
  agentId: string;
  channel: string;
  createdAt: string;
  lastMessageAt: string | null;
  messageCount: number;
  tokenUsage: { prompt: number; completion: number };
  label?: string;
}

export interface ChatMessage {
  id: string;
  role: "user" | "assistant" | "system" | "tool";
  content: string;
  timestamp: string;
  toolCalls?: ToolCall[];
  thinking?: string;
  metadata?: Record<string, unknown>;
}

export interface ToolCall {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  result?: unknown;
  status: "pending" | "running" | "completed" | "error";
  duration?: number;
}

// ── System ──────────────────────────────────────────────
export interface HealthSnapshot {
  status: "healthy" | "degraded" | "error";
  uptimeMs: number;
  version: string;
  services: number;
  agents: number;
  activeSessions: number;
  memoryMb: number;
  cpuPercent: number;
}

export interface StatusSummary {
  connected: boolean;
  gateway: string;
  authMode: string;
  securityAudit?: { summary?: Record<string, number> };
}

export interface LogEntry {
  id: string;
  time: string;
  level: LogLevel;
  subsystem: string;
  message: string;
  raw: string;
  metadata?: Record<string, unknown>;
}

export type LogLevel = "trace" | "debug" | "info" | "warn" | "error" | "fatal";

export interface EventLogEntry {
  id: string;
  event: string;
  ts: number;
  payload: unknown;
}

// ── Config ──────────────────────────────────────────────
export interface ConfigSnapshot {
  config: Record<string, unknown>;
  schema?: JsonSchema;
  version: string;
  lastModified: string;
}

// ── JSON Schema ─────────────────────────────────────────
export interface JsonSchema {
  type?: string;
  title?: string;
  description?: string;
  properties?: Record<string, JsonSchema>;
  items?: JsonSchema;
  required?: string[];
  enum?: unknown[];
  default?: unknown;
  oneOf?: JsonSchema[];
  anyOf?: JsonSchema[];
  additionalProperties?: boolean | JsonSchema;
  format?: string;
  [key: string]: unknown;
}

// ── SSE Events ──────────────────────────────────────────
export type SseEventType =
  | "health"
  | "log"
  | "state_update"
  | "audit_event"
  | "system_stats"
  | "message"
  | "service_change"
  | "agent_status"
  | "tool_call"
  | "registry_event";

export interface SseEvent<T = unknown> {
  type: SseEventType;
  timestamp: string;
  data: T;
}

import { useState, useMemo } from "react";
import { PageHeader, Card, Pill } from "@/components/shell/Primitives";
import { SchemaRenderer } from "@/components/json/SchemaRenderer";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { useEventStore } from "@/stores/event-store";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Search, FlaskConical } from "lucide-react";

interface Skill {
  id: string;
  name: string;
  description: string;
  version: string;
  author: string;
  tags: string[];
  enabled: boolean;
  configSchema: Record<string, unknown>;
  configData: Record<string, unknown>;
}

export default function SkillsPage() {
  const latestState = useEventStore((s) => s.latestState);
  const [skillOverrides, setSkillOverrides] = useState<Record<string, Partial<Skill>>>({});
  const [search, setSearch] = useState("");
  const [testOpen, setTestOpen] = useState(false);
  const [testInput, setTestInput] = useState("");
  const [testMessages, setTestMessages] = useState<{ role: "user" | "assistant"; text: string }[]>([]);

  const skills = useMemo(() => {
    const raw = latestState["skills"] ?? latestState["skills.list"] ?? latestState["skills:list"];
    if (!Array.isArray(raw)) return [] as Skill[];
    return (raw as Skill[]).map((skill) => {
      const overrides = skillOverrides[skill.id] ?? {};
      return {
        ...skill,
        enabled: (overrides.enabled ?? skill.enabled) as boolean,
        configData: { ...(skill.configData ?? {}), ...(overrides.configData ?? {}) },
      };
    });
  }, [latestState, skillOverrides]);

  const [selectedId, setSelectedId] = useState<string>("");

  const filtered = useMemo(
    () => skills.filter((s) =>
      s.name.toLowerCase().includes(search.toLowerCase()) ||
      (s.tags ?? []).some((t) => t.toLowerCase().includes(search.toLowerCase()))
    ),
    [skills, search]
  );

  const selected = skills.find((s) => s.id === selectedId);

  const toggleEnabled = (id: string) => {
    setSkillOverrides((prev) => ({
      ...prev,
      [id]: { ...prev[id], enabled: !(skills.find((s) => s.id === id)?.enabled ?? false) },
    }));
  };

  const updateConfig = (id: string, data: unknown) => {
    setSkillOverrides((prev) => ({
      ...prev,
      [id]: { ...prev[id], configData: data as Record<string, unknown> },
    }));
  };

  const handleTestSend = () => {
    if (!testInput.trim() || !selected) return;
    const userMsg = testInput.trim();
    setTestMessages((prev) => [...prev, { role: "user", text: userMsg }]);
    setTestInput("");
    setTimeout(() => {
      setTestMessages((prev) => [
        ...prev,
        { role: "assistant", text: `[${selected.name}] Simulated response for: "${userMsg}"\n\nConfig: ${JSON.stringify(selected.configData, null, 2)}` },
      ]);
    }, 600);
  };

  return (
    <>
      <PageHeader title="Cognitive Skills" subtitle="Browse, configure, and test domain-specific knowledge augmentations." />

      <div className="grid grid-cols-1 lg:grid-cols-[300px_1fr] gap-4 min-h-0">
        <div className="space-y-3">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
            <Input placeholder="Search skills…" value={search} onChange={(e) => setSearch(e.target.value)} className="pl-8 h-8 text-xs bg-[hsl(var(--bg-elevated))]" />
          </div>
          <div className="space-y-1 max-h-[calc(100vh-220px)] overflow-y-auto pr-1" style={{ scrollbarWidth: "thin" }}>
            {filtered.length === 0 && (
              <p className="text-xs text-muted-foreground text-center py-8">
                {skills.length === 0 ? "No skills detected. Waiting for live data…" : `No skills match "${search}"`}
              </p>
            )}
            {filtered.map((skill) => (
              <button key={skill.id} onClick={() => setSelectedId(skill.id)}
                className={`w-full text-left p-3 rounded-lg border transition-colors ${selectedId === skill.id ? "border-primary/30 bg-primary/5" : "border-transparent hover:bg-muted/30"}`}>
                <div className="flex items-center justify-between gap-2">
                  <span className="text-sm font-medium text-foreground truncate">{skill.name}</span>
                  <Switch checked={skill.enabled} onCheckedChange={() => toggleEnabled(skill.id)} onClick={(e) => e.stopPropagation()} className="shrink-0 scale-75" />
                </div>
                <p className="text-[11px] text-muted-foreground mt-0.5 line-clamp-1">{skill.description}</p>
                <div className="flex gap-1 mt-1.5 flex-wrap">
                  {(skill.tags ?? []).slice(0, 3).map((t) => (
                    <Badge key={t} variant="secondary" className="text-[9px] px-1 py-0">{t}</Badge>
                  ))}
                </div>
              </button>
            ))}
          </div>
        </div>

        {selected ? (
          <div className="space-y-4">
            <Card>
              <div className="flex items-center justify-between gap-3 mb-3">
                <div>
                  <h2 className="text-lg font-bold text-foreground">{selected.name}</h2>
                  <p className="text-xs text-muted-foreground mt-0.5">{selected.description}</p>
                </div>
                <Pill variant={selected.enabled ? "ok" : "default"}>{selected.enabled ? "enabled" : "disabled"}</Pill>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <Badge variant="outline" className="text-[10px]">v{selected.version}</Badge>
                <Badge variant="outline" className="text-[10px]">by {selected.author}</Badge>
                {(selected.tags ?? []).map((t) => <Badge key={t} variant="secondary" className="text-[10px]">{t}</Badge>)}
              </div>
            </Card>
            <Card title="Configuration">
              <div className="mt-2">
                <SchemaRenderer schema={selected.configSchema ?? {}} data={selected.configData ?? {}} onChange={(d) => updateConfig(selected.id, d)} />
              </div>
            </Card>
            <button onClick={() => { setTestMessages([]); setTestOpen(true); }}
              className="flex items-center gap-2 px-4 py-2 rounded-md border border-border text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-muted/30 transition-colors">
              <FlaskConical className="h-4 w-4" /> Test Skill
            </button>
          </div>
        ) : (
          <div className="flex items-center justify-center text-sm text-muted-foreground h-40">
            {skills.length === 0 ? "Waiting for skills data…" : "Select a skill to configure"}
          </div>
        )}
      </div>

      <Dialog open={testOpen} onOpenChange={setTestOpen}>
        <DialogContent className="max-w-lg max-h-[80vh] flex flex-col">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2"><FlaskConical className="h-4 w-4 text-primary" />Test: {selected?.name}</DialogTitle>
            <DialogDescription>Chat with the LLM using this skill's current configuration.</DialogDescription>
          </DialogHeader>
          <div className="flex-1 min-h-0 overflow-y-auto space-y-2 py-2 max-h-[40vh]">
            {testMessages.length === 0 && <p className="text-xs text-muted-foreground text-center py-6">Send a message to test the "{selected?.name}" skill.</p>}
            {testMessages.map((m, i) => (
              <div key={i} className={`p-2.5 rounded-lg text-xs whitespace-pre-wrap ${m.role === "user" ? "bg-primary/10 text-foreground ml-8" : "bg-muted/30 text-foreground mr-8 font-mono"}`}>{m.text}</div>
            ))}
          </div>
          <div className="flex gap-2 pt-2 border-t border-border">
            <Input placeholder="Test this skill…" value={testInput} onChange={(e) => setTestInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && handleTestSend()} className="flex-1 h-8 text-xs" />
            <button onClick={handleTestSend} className="px-3 py-1.5 rounded-md bg-primary text-primary-foreground text-xs font-medium hover:bg-primary/90 transition-colors">Send</button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

