import { useState, useMemo } from "react";
import { PageHeader, Card, Pill, StatusDot } from "@/components/shell/Primitives";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { SchemaRenderer } from "@/components/json/SchemaRenderer";
import { JsonRenderer } from "@/components/json/JsonRenderer";
import { useEventStore } from "@/stores/event-store";
import { cn } from "@/lib/utils";
import {
  ChevronRight, Play, Square, RotateCcw, FileText,
  Cpu, MemoryStick, Clock, Activity,
} from "lucide-react";

/* ── Types ─────────────────────────────────────────────── */

type DinitState = "started" | "stopped" | "starting" | "stopping" | "error";

interface DinitService {
  name: string;
  bus: string;
  pid?: number;
  uniqueName?: string;
  unique_name?: string;
  interfaces?: string[];
  state?: DinitState;
  uptime?: string;
  uptime_secs?: number;
  restarts?: number;
  cpu?: number;
  memory_mb?: number;
  is_activatable?: boolean;
  cmdline?: string;
  metadata?: Record<string, unknown>;
  configSchema?: Record<string, unknown>;
  configData?: Record<string, unknown>;
  actions?: string[];
}

/* ── Helpers ───────────────────────────────────────────── */

const STATE_BADGE: Record<DinitState, { variant: "ok" | "warn" | "danger" | "default"; dot: "ok" | "warn" | "error" | "offline" }> = {
  started: { variant: "ok", dot: "ok" },
  starting: { variant: "warn", dot: "warn" },
  stopping: { variant: "warn", dot: "warn" },
  stopped: { variant: "default", dot: "offline" },
  error: { variant: "danger", dot: "error" },
};

function formatUptime(svc: DinitService): string {
  if (svc.uptime) return svc.uptime;
  if (svc.uptime_secs != null) {
    const s = svc.uptime_secs;
    if (s < 60) return `${s}s`;
    if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
    return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
  }
  return "—";
}

/* ── Component ─────────────────────────────────────────── */

export default function ServicesPage() {
  const { latestState } = useEventStore();
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
  const [localConfigs, setLocalConfigs] = useState<Record<string, Record<string, unknown>>>({});

  const services = useMemo(() => {
    const raw = latestState["services"] ?? latestState["services.list"] ?? latestState["dinit:services"];
    if (Array.isArray(raw)) return raw as DinitService[];
    return [] as DinitService[];
  }, [latestState]);

  const toggleRow = (name: string) => {
    setExpandedRows((prev) => {
      const next = new Set(prev);
      next.has(name) ? next.delete(name) : next.add(name);
      return next;
    });
  };

  const started = services.filter((s) => s.state === "started").length;
  const errored = services.filter((s) => s.state === "error").length;

  return (
    <>
      <PageHeader
        title="Dinit Services"
        subtitle="Service manager control center — monitor, inspect, and manage dinit services."
        actions={
          <button className="px-4 py-2 rounded-md border border-border bg-[hsl(var(--bg-elevated))] text-sm font-medium hover:bg-muted/30 transition-colors">
            Refresh
          </button>
        }
      />

      {/* KPI row */}
      <div className="flex gap-4 text-xs text-muted-foreground mb-4">
        <span className="flex items-center gap-1.5">
          <Activity className="h-3.5 w-3.5 text-primary" />
          <span className="text-foreground font-medium">{services.length}</span> services
        </span>
        {services.length > 0 && (
          <>
            <span className="flex items-center gap-1.5">
              <span className="text-ok font-medium">{started}</span> started
            </span>
            {errored > 0 && (
              <span className="flex items-center gap-1.5">
                <span className="text-danger font-medium">{errored}</span> errors
              </span>
            )}
          </>
        )}
      </div>

      <Card>
        {/* Table header */}
        <div className="hidden md:flex items-center gap-3 px-3 py-2 text-[11px] font-medium text-muted-foreground uppercase tracking-wider border-b border-border/50">
          <div className="w-5" />
          <div className="flex-1">Service</div>
          <div className="w-20 text-center">State</div>
          <div className="w-16 text-center">Bus</div>
          <div className="w-20 text-right">Uptime</div>
          <div className="w-16 text-right">Restarts</div>
          <div className="w-16 text-right">CPU</div>
          <div className="w-20 text-right">Memory</div>
        </div>

        <div className="space-y-0">
          {services.length === 0 && (
            <div className="text-sm text-muted-foreground text-center py-12">
              No dinit services detected. Waiting for live data…
            </div>
          )}
          {services.map((svc) => {
            const isExpanded = expandedRows.has(svc.name);
            const state = svc.state ?? "stopped";
            const badge = STATE_BADGE[state] ?? STATE_BADGE.stopped;
            const uname = svc.uniqueName ?? svc.unique_name;

            return (
              <Collapsible key={svc.name} open={isExpanded} onOpenChange={() => toggleRow(svc.name)}>
                <CollapsibleTrigger asChild>
                  <button className="w-full flex items-center gap-3 px-3 py-3 hover:bg-muted/10 transition-colors border-b border-border/30 last:border-0 text-left">
                    <ChevronRight className={cn("h-3.5 w-3.5 text-muted-foreground transition-transform shrink-0", isExpanded && "rotate-90")} />

                    {/* Service name */}
                    <div className="flex-1 min-w-0">
                      <div className="font-mono text-sm font-medium text-foreground truncate">{svc.name}</div>
                      <div className="text-[11px] text-muted-foreground mt-0.5 truncate md:hidden">
                        {svc.pid != null && `PID ${svc.pid}`} {uname && `· ${uname}`} {svc.interfaces && `· ${svc.interfaces.length} ifaces`}
                      </div>
                      <div className="hidden md:block text-[11px] text-muted-foreground mt-0.5 truncate">
                        {svc.pid != null && `PID ${svc.pid}`} {uname && `· ${uname}`} {svc.interfaces && `· ${svc.interfaces.length} interfaces`}
                      </div>
                    </div>

                    {/* State */}
                    <div className="w-20 flex justify-center">
                      <div className="flex items-center gap-1.5">
                        <StatusDot status={badge.dot} />
                        <Pill variant={badge.variant}>{state}</Pill>
                      </div>
                    </div>

                    {/* Bus */}
                    <div className="w-16 hidden md:flex justify-center">
                      <Badge variant="outline" className="text-[10px] font-mono">{svc.bus}</Badge>
                    </div>

                    {/* Uptime */}
                    <div className="w-20 hidden md:flex justify-end">
                      <span className="text-xs text-muted-foreground font-mono flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {formatUptime(svc)}
                      </span>
                    </div>

                    {/* Restarts */}
                    <div className="w-16 hidden md:flex justify-end">
                      <span className={cn("text-xs font-mono", (svc.restarts ?? 0) > 0 ? "text-warn" : "text-muted-foreground")}>
                        {svc.restarts ?? 0}
                      </span>
                    </div>

                    {/* CPU */}
                    <div className="w-16 hidden md:flex justify-end">
                      {svc.cpu != null ? (
                        <span className="text-xs font-mono text-muted-foreground flex items-center gap-1">
                          <Cpu className="h-3 w-3" />{svc.cpu.toFixed(1)}%
                        </span>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </div>

                    {/* Memory */}
                    <div className="w-20 hidden md:flex justify-end">
                      {svc.memory_mb != null ? (
                        <span className="text-xs font-mono text-muted-foreground flex items-center gap-1">
                          <MemoryStick className="h-3 w-3" />{svc.memory_mb.toFixed(0)} MB
                        </span>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </div>
                  </button>
                </CollapsibleTrigger>

                <CollapsibleContent>
                  <div className="px-4 py-4 ml-6 border-l-2 border-primary/20 space-y-4 bg-muted/5">
                    {/* Action bar */}
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider mr-1">Actions:</span>
                      {(svc.actions ?? ["Restart", "Stop", "View Logs"]).map((action) => {
                        const isDestructive = action.toLowerCase() === "stop";
                        const icon = action.toLowerCase().includes("restart") ? RotateCcw
                          : action.toLowerCase().includes("stop") ? Square
                          : action.toLowerCase().includes("log") ? FileText
                          : Play;
                        const Icon = icon;
                        return (
                          <Button
                            key={action}
                            size="sm"
                            variant={isDestructive ? "destructive" : "outline"}
                            className="h-7 text-xs gap-1.5"
                            onClick={(e) => { e.stopPropagation(); console.log(`[dinit] ${action} → ${svc.name}`); }}
                          >
                            <Icon className="h-3 w-3" />
                            {action}
                          </Button>
                        );
                      })}
                    </div>

                    {/* Metadata / D-Bus schema via JsonRenderer */}
                    {svc.metadata && Object.keys(svc.metadata).length > 0 && (
                      <div>
                        <div className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider mb-2">Service Metadata</div>
                        <JsonRenderer data={svc.metadata} defaultMode="tree" />
                      </div>
                    )}

                    {/* Tunable config via SchemaRenderer */}
                    {svc.configSchema && (
                      <div>
                        <div className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider mb-2">Configuration</div>
                        <SchemaRenderer
                          schema={svc.configSchema}
                          data={localConfigs[svc.name] ?? svc.configData ?? {}}
                          onChange={(val) => setLocalConfigs((p) => ({
                            ...p,
                            [svc.name]: val as Record<string, unknown>,
                          }))}
                        />
                      </div>
                    )}

                    {/* Fallback: show all service data if no specific metadata/config */}
                    {!svc.metadata && !svc.configSchema && (
                      <div>
                        <div className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider mb-2">Service Details</div>
                        <JsonRenderer
                          data={{
                            name: svc.name,
                            bus: svc.bus,
                            pid: svc.pid,
                            unique_name: uname,
                            interfaces: svc.interfaces,
                            is_activatable: svc.is_activatable,
                            cmdline: svc.cmdline,
                          }}
                          defaultMode="tree"
                        />
                      </div>
                    )}
                  </div>
                </CollapsibleContent>
              </Collapsible>
            );
          })}
        </div>
      </Card>
    </>
  );
}

/**
 * Schema-driven Generative UI renderer.
 * Maps JSON Schema types → Shadcn primitives with onChange support.
 */
import { Component, type ErrorInfo, type ReactNode, useCallback, useMemo } from "react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import type { JsonSchema } from "@/types/api";

// ── Error Boundary ──────────────────────────────────────
interface EBProps { children: ReactNode; fallback?: ReactNode }
interface EBState { hasError: boolean; error?: Error }

export class SchemaErrorBoundary extends Component<EBProps, EBState> {
  state: EBState = { hasError: false };
  static getDerivedStateFromError(error: Error) { return { hasError: true, error }; }
  componentDidCatch(error: Error, info: ErrorInfo) { console.error("[SchemaRenderer]", error, info); }
  render() {
    if (this.state.hasError) {
      return this.props.fallback ?? (
        <div className="rounded-md border border-danger/30 bg-danger/5 px-3 py-2 text-xs text-danger font-mono">
          Render error: {this.state.error?.message ?? "unknown"}
        </div>
      );
    }
    return this.props.children;
  }
}

// ── Main Component ──────────────────────────────────────
export interface SchemaRendererProps {
  schema: JsonSchema;
  data: unknown;
  onChange?: (updated: unknown) => void;
  className?: string;
  readOnly?: boolean;
  depth?: number;
  label?: string;
}

export function SchemaRenderer({ schema, data, onChange, className, readOnly = false, depth = 0, label }: SchemaRendererProps) {
  return (
    <SchemaErrorBoundary>
      <SchemaNode schema={schema} data={data} onChange={onChange} className={className} readOnly={readOnly} depth={depth} label={label} />
    </SchemaErrorBoundary>
  );
}

// ── Recursive Node ──────────────────────────────────────
function SchemaNode({ schema, data, onChange, className, readOnly, depth = 0, label }: SchemaRendererProps & { depth: number }) {
  const type = schema.type ?? (schema.enum ? "string" : schema.properties ? "object" : "unknown");

  // boolean → Switch + Badge
  if (type === "boolean") {
    return (
      <FieldRow label={label} description={schema.description} depth={depth} className={className}>
        <div className="flex items-center gap-2">
          <Switch
            checked={Boolean(data)}
            disabled={readOnly}
            onCheckedChange={(v) => onChange?.(v)}
          />
          <Badge variant={data ? "default" : "secondary"} className="text-[10px]">
            {data ? "true" : "false"}
          </Badge>
        </div>
      </FieldRow>
    );
  }

  // string with enum → Select
  if (type === "string" && schema.enum) {
    return (
      <FieldRow label={label} description={schema.description} depth={depth} className={className}>
        <Select
          value={String(data ?? "")}
          disabled={readOnly}
          onValueChange={(v) => onChange?.(v)}
        >
          <SelectTrigger className="h-8 text-xs font-mono bg-secondary border-none">
            <SelectValue placeholder="Select..." />
          </SelectTrigger>
          <SelectContent>
            {schema.enum.map((v) => (
              <SelectItem key={String(v)} value={String(v)} className="text-xs font-mono">{String(v)}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </FieldRow>
    );
  }

  // string → Input
  if (type === "string") {
    return (
      <FieldRow label={label} description={schema.description} depth={depth} className={className}>
        <Input
          type={schema.format === "password" ? "password" : "text"}
          value={String(data ?? "")}
          readOnly={readOnly}
          onChange={(e) => onChange?.(e.target.value)}
          placeholder={schema.default !== undefined ? String(schema.default) : label ?? ""}
          className="h-8 text-xs font-mono bg-secondary border-none"
        />
      </FieldRow>
    );
  }

  // number / integer
  if (type === "number" || type === "integer") {
    const numVal = Number(data ?? 0);
    const min = (schema.minimum as number | undefined) ?? 0;
    const max = (schema.maximum as number | undefined) ?? 100;
    const isPercent = max <= 100 && min >= 0;
    const hasRange = schema.minimum !== undefined || schema.maximum !== undefined;

    // If it looks like a progress/percentage metric in readOnly, show Progress
    if (readOnly && isPercent) {
      return (
        <FieldRow label={label} description={schema.description} depth={depth} className={className}>
          <div className="flex items-center gap-3">
            <Progress value={numVal} className="h-2 flex-1" />
            <span className="text-xs font-mono font-medium text-foreground w-12 text-right">{numVal.toFixed(1)}%</span>
          </div>
        </FieldRow>
      );
    }

    // Editable with range → Slider + number input
    if (hasRange && !readOnly) {
      return (
        <FieldRow label={label} description={schema.description} depth={depth} className={className}>
          <div className="flex items-center gap-3">
            <Slider
              value={[numVal]}
              min={min}
              max={max}
              step={type === "integer" ? 1 : (max - min) / 100}
              onValueChange={([v]) => onChange?.(type === "integer" ? Math.round(v) : v)}
              className="flex-1"
            />
            <span className="text-xs font-mono font-medium text-foreground w-14 text-right">{numVal}</span>
          </div>
        </FieldRow>
      );
    }

    // Default: number input
    return (
      <FieldRow label={label} description={schema.description} depth={depth} className={className}>
        <Input
          type="number"
          value={numVal}
          readOnly={readOnly}
          onChange={(e) => onChange?.(type === "integer" ? parseInt(e.target.value, 10) : parseFloat(e.target.value))}
          className="h-8 text-xs font-mono bg-secondary border-none w-28"
        />
      </FieldRow>
    );
  }

  // array → render items
  if (type === "array") {
    const arr = Array.isArray(data) ? data : [];
    return (
      <FieldRow label={label} description={schema.description} depth={depth} className={className}>
        <div className="space-y-1.5">
          {arr.length === 0 && <span className="text-[11px] text-muted-foreground italic">empty array</span>}
          {arr.map((item, i) => (
            <SchemaNode
              key={i}
              schema={schema.items ?? { type: "string" }}
              data={item}
              onChange={readOnly ? undefined : (v) => {
                const next = [...arr];
                next[i] = v;
                onChange?.(next);
              }}
              readOnly={readOnly}
              depth={depth + 1}
              label={`[${i}]`}
            />
          ))}
        </div>
      </FieldRow>
    );
  }

  // object → Card grouping
  if (type === "object" && schema.properties) {
    const obj = (data && typeof data === "object" && !Array.isArray(data)) ? data as Record<string, unknown> : {};
    const props = schema.properties;
    const required = schema.required ?? [];

    return (
      <div className={cn(
        depth > 0 && "ml-3 pl-3 border-l border-border/50",
        className,
      )}>
        {label && (
          <div className="flex items-baseline gap-2 mb-2">
            <span className="text-xs font-semibold text-foreground">{label}</span>
            {schema.title && <span className="text-[11px] text-muted-foreground">{schema.title}</span>}
          </div>
        )}
        {schema.description && !label && (
          <p className="text-[11px] text-muted-foreground mb-2">{schema.description}</p>
        )}
        <div className={cn(
          "rounded-lg border border-border bg-card/50 p-3 space-y-3",
          depth === 0 && "bg-card",
        )}>
          {schema.title && depth === 0 && (
            <div className="text-[13px] font-semibold text-foreground mb-1">{schema.title}</div>
          )}
          {Object.entries(props).map(([key, propSchema]) => (
            <SchemaNode
              key={key}
              schema={propSchema}
              data={obj[key]}
              onChange={readOnly ? undefined : (v) => {
                onChange?.({ ...obj, [key]: v });
              }}
              readOnly={readOnly}
              depth={depth + 1}
              label={`${key}${required.includes(key) ? " *" : ""}`}
            />
          ))}
        </div>
      </div>
    );
  }

  // Fallback for unknown types
  return (
    <FieldRow label={label} description={schema.description} depth={depth} className={className}>
      <pre className="font-mono text-[11px] text-muted-foreground bg-muted/30 rounded-md px-2 py-1 overflow-auto max-h-24 whitespace-pre-wrap break-all">
        {JSON.stringify(data, null, 2) ?? "null"}
      </pre>
    </FieldRow>
  );
}

// ── Field Row wrapper ───────────────────────────────────
function FieldRow({ label, description, depth, className, children }: {
  label?: string;
  description?: string;
  depth: number;
  className?: string;
  children: ReactNode;
}) {
  return (
    <div className={cn("space-y-1", depth > 0 && depth <= 1 && "", className)}>
      {label && (
        <Label className="text-[11px] font-mono font-medium text-muted-foreground uppercase tracking-wider">
          {label}
        </Label>
      )}
      {children}
      {description && (
        <p className="text-[10px] text-muted-foreground/70">{description}</p>
      )}
    </div>
  );
}

import { useState } from "react";
import { cn } from "@/lib/utils";

interface JsonRendererProps {
  data: unknown;
  defaultMode?: "tree" | "raw";
  maxDepth?: number;
  className?: string;
}

export function JsonRenderer({ data, defaultMode = "tree", maxDepth = 6, className }: JsonRendererProps) {
  const [mode, setMode] = useState<"tree" | "raw">(defaultMode);

  const handleCopy = () => {
    navigator.clipboard.writeText(JSON.stringify(data, null, 2));
  };

  return (
    <div className={cn("rounded-lg border border-border bg-card overflow-hidden", className)}>
      <div className="flex items-center justify-between border-b border-border px-3 py-1.5">
        <span className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider">Inspector</span>
        <div className="flex gap-1">
          {(["tree", "raw"] as const).map((m) => (
            <button key={m} onClick={() => setMode(m)} className={cn(
              "px-2 py-0.5 text-xs rounded-md transition-colors",
              mode === m ? "bg-primary/15 text-primary font-medium" : "text-muted-foreground hover:text-foreground"
            )}>{m === "tree" ? "Tree" : "Raw"}</button>
          ))}
          <button onClick={handleCopy} className="px-2 py-0.5 text-xs rounded-md text-muted-foreground hover:text-foreground transition-colors">Copy</button>
        </div>
      </div>
      <div className="p-3 overflow-auto max-h-[500px] font-mono text-xs leading-relaxed">
        {mode === "raw" ? (
          <pre className="text-foreground whitespace-pre-wrap break-all">{JSON.stringify(data, null, 2)}</pre>
        ) : (
          <JsonTree data={data} depth={0} maxDepth={maxDepth} />
        )}
      </div>
    </div>
  );
}

function JsonTree({ data, depth, maxDepth, label }: { data: unknown; depth: number; maxDepth: number; label?: string }) {
  const [collapsed, setCollapsed] = useState(depth > 2);

  if (data === null || data === undefined) {
    return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-muted-foreground italic">null</span></div>;
  }
  if (typeof data === "boolean") {
    return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className={data ? "text-ok" : "text-danger"}>{String(data)}</span></div>;
  }
  if (typeof data === "number") {
    return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-info">{data}</span></div>;
  }
  if (typeof data === "string") {
    return <div className="flex items-baseline gap-1.5 min-w-0">{label && <span className="text-muted-foreground shrink-0">{label}:</span>}<span className="text-warn break-all">"{data}"</span></div>;
  }

  if (Array.isArray(data)) {
    if (depth >= maxDepth) return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-muted-foreground">[{data.length} items]</span></div>;
    return (
      <div>
        <button onClick={() => setCollapsed(!collapsed)} className="flex items-baseline gap-1.5 hover:text-foreground text-muted-foreground">
          <span className="text-[10px]">{collapsed ? "▸" : "▾"}</span>
          {label && <span>{label}:</span>}
          <span className="text-muted-foreground text-[11px]">[{data.length}]</span>
        </button>
        {!collapsed && <div className="ml-4 border-l border-border/50 pl-3 mt-0.5 space-y-0.5">{data.map((item, i) => <JsonTree key={i} data={item} depth={depth + 1} maxDepth={maxDepth} label={String(i)} />)}</div>}
      </div>
    );
  }

  if (typeof data === "object") {
    const entries = Object.entries(data as Record<string, unknown>);
    if (depth >= maxDepth) return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-muted-foreground">{`{${entries.length} keys}`}</span></div>;
    return (
      <div>
        <button onClick={() => setCollapsed(!collapsed)} className="flex items-baseline gap-1.5 hover:text-foreground text-muted-foreground">
          <span className="text-[10px]">{collapsed ? "▸" : "▾"}</span>
          {label && <span>{label}:</span>}
          <span className="text-muted-foreground text-[11px]">{`{${entries.length}}`}</span>
        </button>
        {!collapsed && <div className="ml-4 border-l border-border/50 pl-3 mt-0.5 space-y-0.5">{entries.map(([key, val]) => <JsonTree key={key} data={val} depth={depth + 1} maxDepth={maxDepth} label={key} />)}</div>}
      </div>
    );
  }

  return <span className="text-foreground">{String(data)}</span>;
}

export { JsonTree };

