import { useEffect, useRef } from "react";
import { stateSync, eventChainService, ovsdbMirror, runtimeMirror, componentRegistry } from "@/grpc/client";
import { useEventStore } from "@/stores/event-store";
import type { StateChange, ChainEvent, OvsdbUpdate, RuntimeMetricUpdate } from "@/grpc/types/operation";
import type { RegistryEvent } from "@/grpc/types/registry";
import { structToObject, valueToJs } from "@/grpc/google/protobuf/struct";

/**
 * Subscribes to all live gRPC-Web server-streams from the operation gateway:
 *   1. StateSync.Subscribe   — D-Bus property changes → latestState
 *   2. EventChain.SubscribeEvents — Audit ledger → events[]
 *   3. OvsdbMirror.Monitor   — OVS bridge/port/interface changes → latestState
 *   4. RuntimeMirror.StreamMetrics — CPU/memory/network metrics → latestStats
 *
 * All streams auto-reconnect on failure with exponential backoff.
 */
export function useEventStream() {
  const abortsRef = useRef<(() => void)[]>([]);
  const retryRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    let mounted = true;

    function connectAll() {
      if (!mounted) return;
      const aborts: (() => void)[] = [];

      const s = useEventStore.getState();
      s.setConnected(false);
      s.setError(null);

      // ── 1. StateSync — live D-Bus property updates ────────────────────
      try {
        const { stream: stateStream, abort: abortState } = stateSync.subscribe({
          includeInitialState: true,
        });
        aborts.push(abortState);

        const stateReader = stateStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await stateReader.read();
              if (done) break;
              const change = value as StateChange;
              const store = useEventStore.getState();

              // Project change into latestState
              const key = change.pluginId
                ? `${change.pluginId}.${change.memberName}`
                : change.memberName;
              store.updateState(key, valueToJs(change.newValue));

              // Track as event
              store.addEvent({
                id: change.changeId || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
                event: "state_update",
                ts: Date.now(),
                payload: change,
              });
              store.incrementEventCount("state_update");

              // Mark connected on first message
              store.setConnected(true);
              store.setError(null);
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`StateSync stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed — will retry
      }

      // ── 2. EventChain — audit ledger stream ──────────────────────────
      try {
        const { stream: chainStream, abort: abortChain } = eventChainService.subscribeEvents({
          fromEventId: 0,
        });
        aborts.push(abortChain);

        const chainReader = chainStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await chainReader.read();
              if (done) break;
              const evt = value as ChainEvent;
              const store = useEventStore.getState();

              store.addEvent({
                id: evt.eventHash || `chain-${evt.eventId}`,
                event: "audit_event",
                ts: Date.now(),
                payload: evt,
              });
              store.incrementEventCount("audit_event");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`EventChain stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      // ── 3. OvsdbMirror.Monitor — OVS changes ─────────────────────────
      try {
        const { stream: ovsStream, abort: abortOvs } = ovsdbMirror.monitor({
          database: "Open_vSwitch",
          monitorRequestsJson: JSON.stringify({
            Bridge: {},
            Port: {},
            Interface: {},
          }),
        });
        aborts.push(abortOvs);

        const ovsReader = ovsStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await ovsReader.read();
              if (done) break;
              const update = value as OvsdbUpdate;
              const store = useEventStore.getState();

              // Project into latestState under ovsdb namespace
              const key = `ovsdb.${update.table}.${update.uuid}`;
              store.updateState(
                key,
                update.newRow ? structToObject(update.newRow) : null,
              );

              store.addEvent({
                id: `ovs-${update.uuid}-${Date.now()}`,
                event: "state_update",
                ts: Date.now(),
                payload: update,
              });
              store.incrementEventCount("state_update");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`OvsdbMirror stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      // ── 4. RuntimeMirror.StreamMetrics — system metrics ───────────────
      try {
        const { stream: metricsStream, abort: abortMetrics } = runtimeMirror.streamMetrics({
          intervalSeconds: 5,
          categories: [],
        });
        aborts.push(abortMetrics);

        const metricsReader = metricsStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await metricsReader.read();
              if (done) break;
              const metric = value as RuntimeMetricUpdate;
              const store = useEventStore.getState();

              // Accumulate metrics into latestStats
              const current = store.latestStats ?? {};
              const labelKey = Object.values(metric.labels || {}).join(".");
              const metricKey = labelKey
                ? `${metric.category}.${metric.name}.${labelKey}`
                : `${metric.category}.${metric.name}`;

              store.setStats({
                ...current,
                [metricKey]: {
                  value: metric.value,
                  unit: metric.unit,
                  labels: metric.labels,
                  timestamp: metric.timestamp,
                },
              });

              store.incrementEventCount("system_stats");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`RuntimeMirror metrics error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      // ── 5. ComponentRegistry.Watch — live agent/component discovery ───
      try {
        const { stream: regStream, abort: abortReg } = componentRegistry.watch({
          componentTypes: [],
          includeExisting: true,
        });
        aborts.push(abortReg);

        const regReader = regStream.getReader();
        (async () => {
          try {
            while (true) {
              const { done, value } = await regReader.read();
              if (done) break;
              const evt = value as RegistryEvent;
              const store = useEventStore.getState();
              const comp = evt.component;

              if (comp) {
                // Maintain a running list of agents under latestState["agents"]
                const existing = (store.latestState["agents"] as Array<Record<string, unknown>>) ?? [];
                const idx = existing.findIndex((a) => a.id === comp.componentId);
                const entry: Record<string, unknown> = {
                  id: comp.componentId,
                  name: comp.name,
                  description: comp.description,
                  status: comp.status === 1 ? "running" : comp.status === 2 ? "offline" : comp.status === 3 ? "offline" : "busy",
                  capabilities: comp.capabilities ?? [],
                  activeSessions: 0,
                  memoryEntries: 0,
                  configSchema: comp.schemaJson ? (() => { try { return JSON.parse(comp.schemaJson); } catch { return {}; } })() : {},
                  configData: comp.metadata ?? {},
                  componentType: comp.componentType,
                  endpoint: comp.endpoint,
                  version: comp.version,
                  lastHeartbeat: comp.lastHeartbeat,
                };

                // Deregistered → remove; otherwise upsert
                if (evt.eventType === 2 /* DEREGISTERED */) {
                  store.updateState("agents", existing.filter((a) => a.id !== comp.componentId));
                } else if (idx >= 0) {
                  const updated = [...existing];
                  updated[idx] = entry;
                  store.updateState("agents", updated);
                } else {
                  store.updateState("agents", [...existing, entry]);
                }
              }

              store.addEvent({
                id: `reg-${evt.component?.componentId}-${Date.now()}`,
                event: "registry_event",
                ts: Date.now(),
                payload: evt,
              });
              store.incrementEventCount("registry_event");
            }
          } catch (err) {
            if (mounted && (err as Error).name !== "AbortError") {
              useEventStore.getState().setError(`ComponentRegistry stream error: ${(err as Error).message}`);
            }
          }
        })();
      } catch {
        // Stream creation failed
      }

      abortsRef.current = aborts;

      // If no streams connected, schedule retry
      if (aborts.length === 0) {
        scheduleRetry();
      }
    }

    function scheduleRetry() {
      if (!mounted) return;
      const store = useEventStore.getState();
      store.setConnected(false);
      store.setError("All gRPC streams disconnected, retrying…");
      retryRef.current = setTimeout(() => {
        cleanup();
        connectAll();
      }, 5000);
    }

    function cleanup() {
      for (const abort of abortsRef.current) {
        try { abort(); } catch { /* ignore */ }
      }
      abortsRef.current = [];
      if (retryRef.current) {
        clearTimeout(retryRef.current);
        retryRef.current = null;
      }
    }

    connectAll();

    return () => {
      mounted = false;
      cleanup();
    };
  }, []);
}

import { create } from "zustand";
import type { HealthSnapshot, LogEntry, Agent, EventLogEntry, SseEventType } from "@/types/api";

interface EventStore {
  connected: boolean;
  health: HealthSnapshot | null;
  logs: LogEntry[];
  agents: Agent[];
  events: EventLogEntry[];
  lastError: string | null;
  eventCounts: Record<string, number>;
  latestState: Record<string, unknown>;
  latestStats: Record<string, unknown> | null;

  setConnected: (v: boolean) => void;
  setHealth: (h: HealthSnapshot) => void;
  addLog: (entry: LogEntry) => void;
  setLogs: (logs: LogEntry[]) => void;
  setAgents: (agents: Agent[]) => void;
  addEvent: (event: EventLogEntry) => void;
  setError: (err: string | null) => void;
  clearLogs: () => void;
  updateState: (key: string, value: unknown) => void;
  setStats: (stats: Record<string, unknown>) => void;
  incrementEventCount: (type: SseEventType) => void;
}

const MAX_LOGS = 1000;
const MAX_EVENTS = 500;

export const useEventStore = create<EventStore>((set) => ({
  connected: false,
  health: null,
  logs: [],
  agents: [],
  events: [],
  lastError: null,
  eventCounts: {},
  latestState: {},
  latestStats: null,

  setConnected: (connected) => set({ connected }),
  setHealth: (health) => set({ health }),
  addLog: (entry) => set((s) => ({ logs: [...s.logs, entry].slice(-MAX_LOGS) })),
  setLogs: (logs) => set({ logs }),
  setAgents: (agents) => set({ agents }),
  addEvent: (event) => set((s) => ({ events: [...s.events, event].slice(-MAX_EVENTS) })),
  setError: (lastError) => set({ lastError }),
  clearLogs: () => set({ logs: [] }),
  updateState: (key, value) => set((s) => ({
    latestState: { ...s.latestState, [key]: value },
  })),
  setStats: (stats) => set({ latestStats: stats }),
  incrementEventCount: (type) => set((s) => ({
    eventCounts: { ...s.eventCounts, [type]: (s.eventCounts[type] || 0) + 1 },
  })),
}));

/**
 * gRPC-Web Transport & Service Clients
 *
 * This module provides the gRPC-Web transport layer and typed service
 * client wrappers for all operation.v1 and operation.registry.v1 services.
 *
 * Uses @protobuf-ts/grpcweb-transport for the wire protocol over
 * tonic-web + Nginx on the backend.
 */

import { GrpcWebFetchTransport } from "@protobuf-ts/grpcweb-transport";
import type { RpcOptions, ServerStreamingCall, UnaryCall } from "@protobuf-ts/runtime-rpc";

// ── Transport Configuration ─────────────────────────────────────────────────

const GRPC_BASE_URL =
  import.meta.env.VITE_GRPC_BASE_URL || "https://dashboard.3tched.com";

let _transport: GrpcWebFetchTransport | null = null;

export function getTransport(): GrpcWebFetchTransport {
  if (!_transport) {
    _transport = new GrpcWebFetchTransport({
      baseUrl: GRPC_BASE_URL,
      format: "binary",
    });
  }
  return _transport;
}

/**
 * Reconfigure the transport (e.g. for testing or endpoint changes).
 */
export function resetTransport(baseUrl?: string): void {
  _transport = new GrpcWebFetchTransport({
    baseUrl: baseUrl ?? GRPC_BASE_URL,
    format: "binary",
  });
}

// ── Generic gRPC-Web call helpers ───────────────────────────────────────────

/**
 * Make a unary gRPC-Web call using fetch.
 * Since we don't have generated @protobuf-ts service clients,
 * we use raw JSON-encoded gRPC-Web (tonic-web supports JSON encoding).
 */
async function grpcUnary<TReq, TResp>(
  service: string,
  method: string,
  request: TReq,
): Promise<TResp> {
  const url = `${GRPC_BASE_URL}/${service}/${method}`;
  const payload = JSON.stringify(request);
  // Encode JSON payload into a gRPC-web binary frame:
  // 1 byte flags (0x00 = uncompressed) + 4 bytes big-endian length + payload
  const encoder = new TextEncoder();
  const payloadBytes = encoder.encode(payload);
  const frame = new Uint8Array(5 + payloadBytes.length);
  frame[0] = 0x00; // no compression
  const dv = new DataView(frame.buffer);
  dv.setUint32(1, payloadBytes.length, false);
  frame.set(payloadBytes, 5);

  const res = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/grpc-web+json",
      "Accept": "application/grpc-web+json",
      "x-grpc-web": "1",
    },
    body: frame,
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`gRPC ${service}/${method} failed: ${res.status} ${text}`);
  }

  const buf = new Uint8Array(await res.arrayBuffer());
  // Parse gRPC-web framed response: skip 5-byte header, read JSON body
  // Tonic-web with JSON codec returns JSON inside the binary frame
  const frames = parseGrpcWebFrames(buf);
  if (frames.length === 0) {
    throw new Error(`gRPC ${service}/${method}: empty response`);
  }
  const decoder = new TextDecoder();
  const body = decoder.decode(frames[0]);
  return JSON.parse(body) as TResp;
}

/** Parse gRPC-web binary frames from a response buffer */
function parseGrpcWebFrames(buf: Uint8Array): Uint8Array[] {
  const frames: Uint8Array[] = [];
  let offset = 0;
  while (offset < buf.length) {
    if (offset + 5 > buf.length) break;
    const flags = buf[offset];
    const dv = new DataView(buf.buffer, buf.byteOffset + offset + 1, 4);
    const len = dv.getUint32(0, false);
    offset += 5;
    if (offset + len > buf.length) break;
    // flags & 0x80 = trailers frame, skip those
    if (!(flags & 0x80)) {
      frames.push(buf.slice(offset, offset + len));
    }
    offset += len;
  }
  return frames;
}

/**
 * Open a server-streaming gRPC-Web call.
 * Returns an async iterable of response messages.
 * Uses fetch + ReadableStream for streaming.
 */
function grpcServerStream<TReq, TResp>(
  service: string,
  method: string,
  request: TReq,
): { stream: ReadableStream<TResp>; abort: () => void } {
  const controller = new AbortController();
  const url = `${GRPC_BASE_URL}/${service}/${method}`;

  const payload = JSON.stringify(request);
  const encoder = new TextEncoder();
  const payloadBytes = encoder.encode(payload);
  const frame = new Uint8Array(5 + payloadBytes.length);
  frame[0] = 0x00;
  const frameDv = new DataView(frame.buffer);
  frameDv.setUint32(1, payloadBytes.length, false);
  frame.set(payloadBytes, 5);

  const responsePromise = fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/grpc-web+json",
      "Accept": "application/grpc-web+json",
      "x-grpc-web": "1",
    },
    body: frame,
    signal: controller.signal,
  });

  const stream = new ReadableStream<TResp>({
    async start(ctrl) {
      try {
        const res = await responsePromise;
        if (!res.ok || !res.body) {
          ctrl.error(new Error(`gRPC stream ${service}/${method} failed: ${res.status}`));
          return;
        }

        const reader = res.body.getReader();
        let pending = new Uint8Array(0);

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          // Append new data to pending buffer
          const merged = new Uint8Array(pending.length + value.length);
          merged.set(pending);
          merged.set(value, pending.length);
          pending = merged;

          // Parse complete gRPC-web frames from buffer
          while (pending.length >= 5) {
            const flags = pending[0];
            const dv = new DataView(pending.buffer, pending.byteOffset + 1, 4);
            const len = dv.getUint32(0, false);
            if (pending.length < 5 + len) break; // incomplete frame

            if (!(flags & 0x80)) {
              // Data frame — decode JSON
              const decoder = new TextDecoder();
              const body = decoder.decode(pending.slice(5, 5 + len));
              try {
                const msg = JSON.parse(body) as TResp;
                ctrl.enqueue(msg);
              } catch {
                // non-JSON data frame
              }
            }
            pending = pending.slice(5 + len);
          }
        }

        ctrl.close();
      } catch (err) {
        if ((err as Error).name !== "AbortError") {
          ctrl.error(err);
        }
      }
    },
  });

  return { stream, abort: () => controller.abort() };
}

